/* diag_rsa_oaep.c * * Reproduces kat/cavp_extended.c::run_rsa_oaep_roundtrip exactly with * a print + ERR_print_errors at every potential failure point, so we * can see which EVP call fails and what OpenSSL error chain it produces. * * Also runs the PSS roundtrip first for comparison (since PSS passes * in dev mode but OAEP fails). * * Build : cc disabled/diag_rsa_oaep.c -lcrypto -o /tmp/diag_oaep * Run : /tmp/diag_oaep * * License : Apache-2.0 */ #include <stdio.h> #include <string.h> #include <openssl/evp.h> #include <openssl/rsa.h> #include <openssl/err.h> #include <openssl/opensslv.h> static const unsigned char msg[16] = "FreeHSM RSA KAT!"; static void dump_err(const char *who) { fprintf(stderr, " [%s] FAIL
", who); fprintf(stderr, " OpenSSL error chain :
"); ERR_print_errors_fp(stderr); fprintf(stderr, "
"); } static EVP_PKEY *gen_rsa_2048(void) { EVP_PKEY *pkey = NULL; EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL); if (!ctx) { dump_err("EVP_PKEY_CTX_new_id(RSA)"); return NULL; } if (EVP_PKEY_keygen_init(ctx) <= 0) { dump_err("keygen_init"); goto end; } if (EVP_PKEY_CTX_set_rsa_keygen_bits(ctx, 2048) <= 0) { dump_err("set_keygen_bits"); goto end; } if (EVP_PKEY_keygen(ctx, &pkey) <= 0) { dump_err("EVP_PKEY_keygen"); pkey = NULL; goto end;
